const { default: addInstanceMethod } = require('../../../../src/plugins/instance/main.js');

describe('addInstanceMethod', () => {
  let plugin;
  let plugins;
  let ErrorClass;
  let methodName;
  let methodFunc;

  beforeEach(() => {
    plugin = { name: 'testPlugin' };
    plugins = [];
    ErrorClass = function CustomError(message) {
      this.name = 'CustomError';
      this.message = message;
    };
    methodName = 'customMethod';
    methodFunc = jest.fn(function() {
      return `instance: ${this.message}`;
    });
  });

  it('should add a method to the ErrorClass prototype and as a static method', () => {
    addInstanceMethod(plugin, plugins, ErrorClass, methodName, methodFunc);

    expect(typeof ErrorClass.prototype[methodName]).toBe('function');
    expect(typeof ErrorClass[methodName]).toBe('function');
  });

  it('should bind the instance method to the current instance', () => {
    addInstanceMethod(plugin, plugins, ErrorClass, methodName, methodFunc);

    const err = new ErrorClass('test error');
    const result = err.customMethod();

    expect(methodFunc).toHaveBeenCalled();
    expect(result).toBe('instance: test error');
  });

  it('should make the added methods non-enumerable', () => {
    addInstanceMethod(plugin, plugins, ErrorClass, methodName, methodFunc);

    const instanceKeys = Object.keys(ErrorClass.prototype);
    const staticKeys = Object.keys(ErrorClass);

    expect(instanceKeys).not.toContain(methodName);
    expect(staticKeys).not.toContain(methodName);
  });

  it('should throw TypeError if ErrorClass is not a function', () => {
    expect(() => {
      addInstanceMethod(plugin, plugins, 'NotAFunction', methodName, methodFunc);
    }).toThrow(TypeError);
  });

  it('should throw TypeError if methodName is not a string', () => {
    expect(() => {
      addInstanceMethod(plugin, plugins, ErrorClass, 123, methodFunc);
    }).toThrow(TypeError);
  });

  it('should throw TypeError if methodFunc is not a function', () => {
    expect(() => {
      addInstanceMethod(plugin, plugins, ErrorClass, methodName, 'NotAFunction');
    }).toThrow(TypeError);
  });

  it('should preserve existing properties on ErrorClass and prototype', () => {
    ErrorClass.staticProp = 'static';
    ErrorClass.prototype.instanceProp = 'instance';

    addInstanceMethod(plugin, plugins, ErrorClass, methodName, methodFunc);

    expect(ErrorClass.staticProp).toBe('static');
    expect(ErrorClass.prototype.instanceProp).toBe('instance');
  });
});

