const mainModule = require('../../../../src/plugins/properties/main');
const applyPluginProperties = mainModule.applyPluginProperties || mainModule;

describe('applyPluginProperties', () => {
  let error;
  let plugin;
  let plugins;

  beforeEach(() => {
    error = {
      message: 'Test error',
      code: 'ERR_TEST'
    };
    plugin = {
      fullName: 'test-plugin',
      properties: jest.fn()
    };
    plugins = [
      { fullName: 'plugin-a' },
      { fullName: 'plugin-b' },
      plugin
    ];
  });

  it('should apply properties to the error object', () => {
    const newProps = {
      severity: 'high',
      category: 'network'
    };
    plugin.properties.mockReturnValue(newProps);

    applyPluginProperties(error, plugin, plugins);

    expect(plugin.properties).toHaveBeenCalledWith(error, plugins);
    expect(error).toEqual(expect.objectContaining(newProps));
  });

  it('should throw TypeError if plugin.properties is not defined', () => {
    delete plugin.properties;

    expect(() => applyPluginProperties(error, plugin, plugins)).toThrow(TypeError);
  });

  it('should do nothing if plugin.properties returns undefined', () => {
    plugin.properties.mockReturnValue(undefined);

    applyPluginProperties(error, plugin, plugins);

    expect(plugin.properties).toHaveBeenCalled();
    expect(error).toEqual({
      message: 'Test error',
      code: 'ERR_TEST'
    });
  });

  it('should throw TypeError if properties returns a non-object', () => {
    plugin.properties.mockReturnValue('invalid-string');

    expect(() => applyPluginProperties(error, plugin, plugins)).toThrow(TypeError);
  });

  it('should throw TypeError if properties returns null', () => {
    plugin.properties.mockReturnValue(null);

    expect(() => applyPluginProperties(error, plugin, plugins)).toThrow(TypeError);
  });

  it('should throw TypeError if properties returns an array', () => {
    plugin.properties.mockReturnValue([]);

    expect(() => applyPluginProperties(error, plugin, plugins)).toThrow(TypeError);
  });

  it('should throw TypeError if properties returns an instance of a class', () => {
    class CustomProps {
      constructor() {
        this.id = 1;
      }
    }
    plugin.properties.mockReturnValue(new CustomProps());

    expect(() => applyPluginProperties(error, plugin, plugins)).toThrow(TypeError);
  });

  it('should merge properties with existing ones on the error object', () => {
    const newProps = {
      timestamp: 123456,
      stack: 'new-stack-trace'
    };
    plugin.properties.mockReturnValue(newProps);

    applyPluginProperties(error, plugin, plugins);

    expect(error).toEqual({
      message: 'Test error',
      code: 'ERR_TEST',
      timestamp: 123456,
      stack: 'new-stack-trace'
    });
  });

  it('should pass the correct arguments to the properties function', () => {
    const newProps = { foo: 'bar' };
    plugin.properties.mockReturnValue(newProps);

    applyPluginProperties(error, plugin, plugins);

    expect(plugin.properties).toHaveBeenCalledTimes(1);
    expect(plugin.properties).toHaveBeenCalledWith(error, plugins);
  });
});

