const shapeMain = require('../../../../src/plugins/shape/main');

// Handle exports robustly: check if named export exists, otherwise assume default
const normalizePlugin = typeof shapeMain === 'function' ? shapeMain : shapeMain.normalizePlugin;

describe('normalizePlugin', () => {
  let MockError;

  beforeEach(() => {
    MockError = class CustomError extends Error {
      constructor(message) {
        super(message);
        this.name = 'MockError';
      }
    };
  });

  it('should throw a TypeError if the plugin is not a plain object (null)', () => {
    expect(() => normalizePlugin(null, MockError)).toThrow(TypeError);
  });

  it('should throw a TypeError if the plugin is not a plain object (array)', () => {
    expect(() => normalizePlugin([], MockError)).toThrow(TypeError);
  });

  it('should throw a TypeError if the plugin is not a plain object (function)', () => {
    expect(() => normalizePlugin(() => {}, MockError)).toThrow(TypeError);
  });

  it('should throw a TypeError if the plugin is not a plain object (string)', () => {
    expect(() => normalizePlugin('string', MockError)).toThrow(TypeError);
  });

  it('should throw a TypeError if the plugin is not a plain object (number)', () => {
    expect(() => normalizePlugin(123, MockError)).toThrow(TypeError);
  });

  it('should throw a TypeError if the plugin is not a plain object (boolean)', () => {
    expect(() => normalizePlugin(true, MockError)).toThrow(TypeError);
  });

  it('should throw a TypeError if the plugin is a class instance (not plain object)', () => {
    class PluginClass {}
    expect(() => normalizePlugin(new PluginClass(), MockError)).toThrow(TypeError);
  });

  it('should return the normalized plugin object for a valid empty plugin', () => {
    const plugin = {};
    const result = normalizePlugin(plugin, MockError);

    expect(result).toBeDefined();
    expect(result).not.toBe(plugin);
    expect(typeof result).toBe('object');
  });

  it('should normalize a plugin with a valid name string', () => {
